169	/** Parses the arguments after `status`. Throws UsageError on anything it does not accept. */
170	export function parseStatusArgs(args: string[]): StatusArgs {
171	  let db = DEFAULT_DB;
172	  let budget: string | undefined;
173	  for (let i = 0; i < args.length; i++) {
174	    const a = args[i]!;
175	    const eq = a.indexOf("=");
176	    const name = eq === -1 ? a : a.slice(0, eq);
177	    const takeValue = (): string => {
178	      if (eq !== -1) return a.slice(eq + 1);
