      makeRow({ setup: "beta", field: "beta-one", delta: 6 }),
      makeRow({ setup: "alpha", field: "alpha-two", delta: 7 }),
    ],
    baseOpts,
  );

  const alphaOne = result.indexOf("alpha-one");
  const alphaTwo = result.indexOf("alpha-two");
  const betaOne = result.indexOf("beta-one");

